"""Round2 CaseB: completed logs only. No NPU, simulator, optimizer or production write."""
import json
from pathlib import Path
from collections import Counter
import numpy as np
HERE=Path(__file__).resolve().parent
r=json.loads((HERE/'round1_result.json').read_text())
a=json.loads((HERE/'round1_analysis.json').read_text())
assert a['next_round_decision']=='CONTINUE_CASE_B_LOGS_ONLY'
rows=[json.loads(l) for l in (HERE/'proposal_logs.jsonl').read_text().splitlines()]
assert rows==r['records'] and len(rows)==40
rejects=[x for x in rows if x['decision']=='FULL_REJECT']
mins=[]
for row in rejects:
 at=row['backtracking_attempts'][-1]
 assert at['fraction']==.0625 and len(row['backtracking_attempts'])==4
 mins.append({'block':row['block'],'previous_accepted_q1_gain':row['accepted_q']['q1_gain'],'block_q_increment':at['block_q_increment'],'success':at['evaluation']['behavior']['success_count'],'lengths':[e['length'] for e in at['evaluation']['behavior']['episodes']],'sim_errors':at['evaluation']['behavior']['sim_errors'],'competence_safe':at['competence_safe'],'q1_improving':at['q1_improving']})
def stats(v):return {'min':float(np.min(v)),'median':float(np.median(v)),'max':float(np.max(v))}
rescued=[]
for row in rows:
 if row['decision']=='PARTIAL_ACCEPT':
  full=row['full_candidate'];at=row['backtracking_attempts'][-1]
  rescued.append({'block':row['block'],'fraction':at['fraction'],'full_block_q':full['block_q_increment'],'partial_block_q':at['block_q_increment'],'q_retained_fraction':row['block_q_retained_fraction'],'full_success':full['evaluation']['behavior']['success_count'],'partial_success':at['evaluation']['behavior']['success_count'],'accepted_cumulative_q1':row['accepted_q']['q1_gain']})
strata=[]
for lo,hi in [(1,5),(6,10),(11,40)]:
 v=[x for x in rows if lo<=x['block']<=hi]
 strata.append({'blocks':[lo,hi],'full_accept':sum(x['decision']=='FULL_ACCEPT' for x in v),'partial_accept':sum(x['decision']=='PARTIAL_ACCEPT' for x in v),'full_reject':sum(x['decision']=='FULL_REJECT' for x in v),'selected_fractions':[x['selected_fraction'] for x in v if x['selected_fraction'] is not None],'endpoint_q1_gain':v[-1]['accepted_q']['q1_gain']})
out={'previous_conclusion':a['classification'],'question':'Do fully rejected directions at the smallest preregistered fraction0.0625still improve fixed-probe Q while losing acceptance competence?','experiment_type':'READ_ONLY_EXISTING_LOG_ANALYSIS','simulator_used':False,'new_env_steps':0,'new_actor_updates':0,'new_critic_updates':0,'four_env_contract':'No new simulator. Reused only completed invocations with initialized/used/closed4; incomplete attempts excluded in final audit.','fully_read_proposal_rows':len(rows),'fully_rejected_min_fraction_cases':len(mins),'min_fraction_q1_positive_count':sum(x['block_q_increment']['q1_gain']>0 for x in mins),'min_fraction_q2_positive_count':sum(x['block_q_increment']['q2_gain']>0 for x in mins),'min_fraction_both_q_positive_and_competence_failed_count':sum(x['block_q_increment']['q1_gain']>0 and x['block_q_increment']['q2_gain']>0 and x['success']<3 and x['sim_errors']==0 for x in mins),'min_fraction_success_histogram':dict(Counter(str(x['success'])+'/4' for x in mins)),'min_fraction_q_stats':{k:stats([x['block_q_increment'][k] for x in mins]) for k in ['q1_gain','q2_gain','qmean_gain']},'full_candidates_both_q_improving_count':sum(x['full_candidate']['block_q_increment']['q1_gain']>0 and x['full_candidate']['block_q_increment']['q2_gain']>0 for x in rows),'rescued_cases':rescued,'chronological_strata':strata,'last_accepted_block':max(x['block'] for x in rows if x['decision']!='FULL_REJECT'),'trailing_full_rejections':30,'q1_fraction_of_collapse_target':a['q1_fraction_collapse_target'],'accepted_q_efficiency':a['accepted_q_efficiency'],'updated_classification':a['classification'],'causal_interpretation':'Same-direction shortening does rescue some early proposals, but85%of full proposals have no competent point on the tested grid. All34fully rejected minimum-fraction candidates still improve both twins. After block10,30proposals reject without further accumulation. This supports state-dependent Q/competence incompatibility in the tested finite local grid, not direction universally wrong and not a step-size-only fix.','substantial_q_interpretation':'33.20%of collapse target exceeds the20%suppression criterion, so BACKTRACKING_SUPPRESSES_Q_OPTIMIZATION is not the prescribed label. Some Q progress is retained but long-run accumulation stalls and matched-Q rescue is not demonstrated.','safe_fraction_trend':'Accepted fractions0.25,0.125,0.5,0.5,0.125,0.0625are not monotone. Late proposals mostly have no passing grid fraction; treating rejection as fraction0would falsely imply an observed continuous shrinking safe radius.','does_this_explain_formal_collapse':'Supports the Actor-only Q-ascent versus competence mismatch and harmful unrestricted commitments; does not uniquely identify a Critic/TD/Bellman architecture cause or reproduce resumed formal training.','limits':['Finite grid ends at0.0625; no result for infinitesimal steps.','Four repeatedly used acceptance seeds are not broad competence guarantees; heldout never controls acceptance.','Later directions change after partial commits, so these are not paired retests of the prior38directions.','Fixed overlapping replay batches and repeated seeds mean these cases are not independent population samples.','Partial acceptance combines parameter interpolation with optimizer/RNG rollback and nominal schedule advancement.','LOW and MID heldout states are UNMATCHED; endpoint heldout unmeasured.'],'decision':'STOP','why_no_round3':'Within the preregistered finite grid, CaseB is resolved by existing logs. Resolving smaller-than-grid behavior requires a separately preregistered future experiment, not extending this budget.','min_fraction_cases':mins}
p=HERE/'round2_analysis.json';assert not p.exists();p.write_text(json.dumps(out,indent=2,allow_nan=False)+'\n')
d=HERE/'round2';d.mkdir(exist_ok=False)
(d/'ROUND_REPORT.md').write_text('# ROUND2 — Case B\n\nPrevious conclusion: '+out['previous_conclusion']+'\n\nQuestion: '+out['question']+'\n\nWhy next most informative: distinguishes loss of Q improvement from competence failure at the smallest tested movement without a new rollout.\n\nExperiment type: read-only completed-log analysis.\n\nSimulator used? no.\n\n4-env contract: '+out['four_env_contract']+'\n\nResult:\n'+json.dumps(out,indent=2)+'\n\nCausal interpretation: '+out['causal_interpretation']+'\n\nDoes this explain formal collapse? '+out['does_this_explain_formal_collapse']+'\n\nDecision: STOP.\n')
print(json.dumps({k:v for k,v in out.items() if k!='min_fraction_cases'},indent=2))
